void setup_primitives(Engine& engine)
{
    // Load the cube primitive model into the engine
    engine.models().load("prim::cube", cube, ".glb");
    engine.models().load("prim::capsule", capsule, ".glb");
    engine.models().load("prim::cylinder", cylinder, ".glb");
    engine.models().load("prim::plane", plane, ".glb");
    engine.models().load("prim::sphere", sphere, ".glb");
    engine.models().load("prim::torus", torus, ".glb");
}

graphics::ModelHandle get_primitive(PrimitiveType primitive, Engine& engine)
{
    switch (primitive)
    {
        case PrimitiveType::Cube:
            return engine.models().find("prim::cube");
        case Sphere:
            return engine.models().find("prim::sphere");
        case Capsule:
            return engine.models().find("prim::capsule");
        case Cylinder:
            return engine.models().find("prim::cylinder");
        case Torus:
            return engine.models().find("prim::torus");
        case Plane:
            return engine.models().find("prim::plane");
        default:
            assert(false && "Unknown primitive type");
            return graphics::ModelHandle{};
    }
}
